uniform vec4 uP;   // x = time, y = dt, z = life seconds
out vec4 fragColor;
float hash(vec2 p){ return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453); }
void main(){
    vec2 uv = vUV.st;
    vec4 cur = texture(sTD2DInputs[0], uv);
    vec4 st  = texture(sTD2DInputs[1], uv);
    float h  = hash(uv) * uP.w;   // w = spread of respawn times (0 = all particles together)
    float g1 = floor(uP.x / uP.z + h);
    float g0 = floor((uP.x - uP.y) / uP.z + h);
    fragColor = vec4(g1 != g0 ? st.rgb : cur.rgb, 1.0);
}

// Example Pixel Shader

// uniform float exampleUniform;

out vec4 fragColor;
void main()
{
	// vec4 color = texture(sTD2DInputs[0], vUV.st);
	vec4 color = vec4(1.0);
	fragColor = TDOutputSwizzle(color);
}

// Example Compute Shader

// uniform float exampleUniform;

layout (local_size_x = 8, local_size_y = 8) in;
void main()
{
	vec4 color;
	//color = texelFetch(sTD2DInputs[0], ivec2(gl_GlobalInvocationID.xy), 0);
	color = vec4(1.0);
	// We need to use TDImageStoreOutput() so that 8-bit textures that are sRGB
	// encoded can be written to correctly from incoming linear values.
	// imageStore() does not do this automatically, while pixel shader outputs do.
	TDImageStoreOutput(0, gl_GlobalInvocationID, color);
}
